import { Router } from "express";
import { db, seoPagesTable } from "@workspace/db";
import { and, desc, eq } from "drizzle-orm";
import { getSetting } from "./settings";
import { replaceLegacyCompanyName } from "../lib/companyName";
import { normalizeSeoKeywords, normalizeSeoTags } from "../lib/seoKeywords";
import {
  analyzeRankMathSeo,
  buildSeoPageRankMathInput,
  evaluateSeoPageIndexability,
  normalizeRankMathCanonical,
} from "@workspace/seo-rank-math";
import { requireAdmin, requireSectionPermission } from "../middleware/adminAuth";
import { refreshSitemapFile } from "./sitemap";
import { getSiteOrigin } from "../lib/siteOrigin";

const router = Router();

function normalizeSlug(value: unknown, fallback = "صفحة-seo"): string {
  const source = typeof value === "string" ? value : "";
  const slug = source
    .trim()
    .replace(/[\s_]+/g, "-")
    .replace(/[^\u0600-\u06FFa-zA-Z0-9-]/g, "")
    .replace(/-+/g, "-")
    .replace(/^-|-$/g, "")
    .slice(0, 100);
  return slug || `${fallback}-${Date.now()}`;
}

function castRow(row: any, companyName: string) {
  const text = (value: unknown) => replaceLegacyCompanyName(value, companyName);

  return {
    id: row.id,
    title: text(row.title ?? ""),
    slug: row.slug ?? row.seoSlug ?? row.seo_slug ?? "",
    targetKeyword: text(row.targetKeyword ?? row.target_keyword ?? ""),
    content: text(row.content ?? ""),
    excerpt: text(row.excerpt ?? ""),
    coverImage: text(row.coverImage ?? row.cover_image ?? ""),
    category: text(row.category ?? "خدمات التنظيف"),
    tags: text(row.tags ?? "[]"),
    status: row.status ?? "draft",
    publishedAt: row.publishedAt ?? row.published_at ?? null,
    viewCount: row.viewCount ?? row.view_count ?? 0,
    isActive: Boolean(row.isActive ?? row.is_active ?? true),
    order: row.order ?? 0,
    seoTitle: text(row.seoTitle ?? row.seo_title ?? ""),
    seoDescription: text(row.seoDescription ?? row.seo_description ?? ""),
    seoKeywords: text(row.seoKeywords ?? row.seo_keywords ?? ""),
    seoSlug: row.seoSlug ?? row.seo_slug ?? row.slug ?? "",
    ogImage: text(row.ogImage ?? row.og_image ?? ""),
    canonicalUrl: text(row.canonicalUrl ?? row.canonical_url ?? ""),
    createdAt: row.createdAt ?? row.created_at,
    updatedAt: row.updatedAt ?? row.updated_at,
  };
}

const publicFilter = and(eq(seoPagesTable.status, "published"), eq(seoPagesTable.isActive, true));

type SeoPublishInput = Record<string, any>;

/**
 * Publishing is the irreversible SEO action: drafts may be incomplete, but a
 * published page must have enough visible substance to avoid thin/indexation
 * accidents. Cover images remain a warning rather than a hard block.
 */
async function validatePublish(input: SeoPublishInput, siteUrl: string, currentId?: number): Promise<string | null> {
  if (input.status !== "published") return null;
  const title = String(input.title ?? "").trim();
  const content = String(input.content ?? "").replace(/<[^>]+>/g, " ").replace(/\s+/g, " ").trim();
  const seoTitle = String(input.seoTitle ?? "").trim();
  const seoDescription = String(input.seoDescription ?? "").trim();
  const slug = String(input.seoSlug ?? input.slug ?? "").trim();
  if (!title) return "لا يمكن نشر صفحة SEO بدون عنوان ظاهر (H1).";
  if (content.length < 120) return "لا يمكن نشر صفحة SEO بمحتوى قصير؛ أضف شرحاً مفيداً قبل النشر.";
  if (!seoTitle) return "لا يمكن نشر صفحة SEO بدون عنوان SEO.";
  if (!seoDescription) return "لا يمكن نشر صفحة SEO بدون وصف SEO.";
  if (!slug) return "لا يمكن نشر صفحة SEO بدون رابط واضح.";

  const expectedCanonical = `${siteUrl}/page/${encodeURIComponent(slug)}`;
  const canonical = normalizeRankMathCanonical(
    input.canonicalUrl ?? input.canonical_url,
    expectedCanonical,
  );
  const indexability = evaluateSeoPageIndexability({
    title,
    targetKeyword: String(input.targetKeyword ?? input.target_keyword ?? ""),
    seoTitle: seoTitle || title,
    content: String(input.content ?? ""),
    slug,
    canonical,
    expectedCanonical,
  });
  if (!indexability.indexable) {
    return `لا يمكن النشر أو الفهرسة وفق سياسة الصفحة: ${indexability.reason} (${indexability.contentChars} حرفاً مرئياً).`;
  }

  const rankMath = buildSeoPageRankMathInput({
    ...input,
    slug,
    seoSlug: slug,
    canonicalUrl: canonical,
  });
  const analysis = analyzeRankMathSeo({
    ...rankMath,
    title,
    seoTitle: seoTitle || title,
    description: seoDescription,
    canonical,
  });
  if (!analysis.publishable) {
    return `تعذر النشر عبر بوابة Rank Math الداخلية (${analysis.score}/100): ${analysis.blockingIssues.join("، ")}`;
  }

  const duplicateSlug = await db
    .select({ id: seoPagesTable.id })
    .from(seoPagesTable)
    .where(eq(seoPagesTable.slug, slug));
  if (duplicateSlug.some(row => row.id !== currentId)) return "هذا الرابط مستخدم من صفحة أخرى.";

  const duplicateContent = await db.select({
    id: seoPagesTable.id,
    content: seoPagesTable.content,
  }).from(seoPagesTable);
  const normalized = content.toLocaleLowerCase();
  if (duplicateContent.some(row =>
    row.id !== currentId &&
    String(row.content ?? "").replace(/<[^>]+>/g, " ").replace(/\s+/g, " ").trim().toLocaleLowerCase() === normalized
  )) {
    return "لا يمكن نشر محتوى مطابق لمحتوى صفحة منشورة أو محفوظة أخرى.";
  }
  return null;
}

// Public page index is useful for internal linking and for future page hubs.
router.get("/pages", async (_req, res) => {
  try {
    const rows = await db.select().from(seoPagesTable).where(publicFilter).orderBy(desc(seoPagesTable.publishedAt));
    const companyName = await getSetting("company_name");
    // Published, active SEO pages are public content. Editorial quality
    // checks still protect publishing, but must not silently turn a public
    // page into a noindex/404 page after it has been published.
    return res.json(rows.map(row => castRow(row, companyName)));
  } catch {
    return res.json([]);
  }
});

// GET /pages/:slug — published SEO landing page
router.get("/pages/:slug", async (req, res) => {
  try {
    const rows = await db
      .select()
      .from(seoPagesTable)
      .where(and(eq(seoPagesTable.slug, req.params.slug), publicFilter));
    if (!rows.length) return res.status(404).json({ error: "Not found" });

    try {
      const client = (db as any).$client;
      client.prepare("UPDATE seo_pages SET view_count = view_count + 1 WHERE id = ?").run(rows[0].id);
    } catch {}

    return res.json(castRow(rows[0], await getSetting("company_name")));
  } catch (error) {
    return res.status(500).json({ error: String(error) });
  }
});

// Admin list includes drafts and unpublished keyword pages.
router.get("/admin/seo-pages", requireAdmin, requireSectionPermission("seo_pages"), async (_req, res) => {
  try {
    const rows = await db.select().from(seoPagesTable).orderBy(desc(seoPagesTable.createdAt));
    const companyName = await getSetting("company_name");
    return res.json(rows.map(row => castRow(row, companyName)));
  } catch {
    return res.json([]);
  }
});

router.post("/admin/seo-pages", requireAdmin, requireSectionPermission("seo_pages"), async (req, res) => {
  try {
    const body = req.body as Record<string, any>;
    const now = new Date().toISOString();
    const slug = normalizeSlug(body.seoSlug || body.slug || body.title, "صفحة-seo");
    const siteUrl = await getSiteOrigin(req);
    const expectedCanonical = `${siteUrl}/page/${encodeURIComponent(slug)}`;
    const canonicalUrl = normalizeRankMathCanonical(body.canonicalUrl, expectedCanonical);
    if (body.status === "published") {
      const publishError = await validatePublish({ ...body, seoSlug: slug, canonicalUrl }, siteUrl, undefined);
      if (publishError) return res.status(422).json({ error: publishError });
    }
    const companyName = await getSetting("company_name");
    const [row] = await db.insert(seoPagesTable).values({
      title: replaceLegacyCompanyName(body.title || "صفحة SEO جديدة", companyName),
      slug,
      targetKeyword: replaceLegacyCompanyName(body.targetKeyword ?? "", companyName),
      content: replaceLegacyCompanyName(body.content ?? "", companyName),
      excerpt: replaceLegacyCompanyName(body.excerpt ?? "", companyName),
      coverImage: replaceLegacyCompanyName(body.coverImage ?? "", companyName),
      category: replaceLegacyCompanyName(body.category ?? "خدمات التنظيف", companyName),
      tags: normalizeSeoTags(
        replaceLegacyCompanyName(Array.isArray(body.tags) ? JSON.stringify(body.tags) : (body.tags ?? "[]"), companyName),
        replaceLegacyCompanyName(body.targetKeyword ?? "", companyName),
      ),
      status: body.status === "published" ? "published" : "draft",
      publishedAt: body.status === "published" ? (body.publishedAt || now) : (body.publishedAt ?? null),
      viewCount: 0,
      isActive: body.isActive ?? true,
      order: Number(body.order) || 0,
      seoTitle: replaceLegacyCompanyName(body.seoTitle ?? "", companyName),
      seoDescription: replaceLegacyCompanyName(body.seoDescription ?? "", companyName),
      seoKeywords: normalizeSeoKeywords(
        replaceLegacyCompanyName(body.seoKeywords ?? "", companyName),
        replaceLegacyCompanyName(body.targetKeyword ?? "", companyName),
      ),
      seoSlug: slug,
      ogImage: replaceLegacyCompanyName(body.ogImage ?? "", companyName),
      canonicalUrl: replaceLegacyCompanyName(canonicalUrl, companyName),
      createdAt: now,
      updatedAt: now,
    }).returning();
    await refreshSitemapFile(req);
    return res.status(201).json(castRow(row, companyName));
  } catch (error) {
    return res.status(500).json({ error: String(error) });
  }
});

router.patch("/admin/seo-pages/:id", requireAdmin, requireSectionPermission("seo_pages"), async (req, res) => {
  try {
    const id = Number.parseInt(String(req.params.id), 10);
    const body = req.body as Record<string, any>;
    const now = new Date().toISOString();
    const companyName = await getSetting("company_name");
    const [current] = await db.select().from(seoPagesTable).where(eq(seoPagesTable.id, id));
    if (!current) return res.status(404).json({ error: "Not found" });
    const nextSlug = normalizeSlug(
      body.seoSlug ?? body.slug ?? current.seoSlug ?? current.slug,
      body.title || current.title || "صفحة-seo",
    );
    const siteUrl = await getSiteOrigin(req);
    const expectedCanonical = `${siteUrl}/page/${encodeURIComponent(nextSlug)}`;
    const canonicalUrl = normalizeRankMathCanonical(
      body.canonicalUrl ?? current.canonicalUrl,
      expectedCanonical,
    );
    const seoFieldsChanged = ["title", "targetKeyword", "content", "seoTitle", "seoDescription", "seoKeywords", "seoSlug", "slug", "canonicalUrl"]
      .some(key => body[key] !== undefined && String(body[key] ?? "") !== String((current as any)[key] ?? ""));
    if ((body.status === "published" && current.status !== "published") ||
        (current.status === "published" && seoFieldsChanged) ||
        (body.isActive === true && !current.isActive)) {
      const publishError = await validatePublish({
        ...current,
        ...body,
        slug: nextSlug,
        seoSlug: nextSlug,
        canonicalUrl,
      }, siteUrl, id);
      if (publishError) return res.status(422).json({ error: publishError });
    }
    const update: Record<string, any> = { updatedAt: now };

    if (body.title !== undefined) update.title = replaceLegacyCompanyName(body.title, companyName);
    if (body.targetKeyword !== undefined) update.targetKeyword = replaceLegacyCompanyName(body.targetKeyword, companyName);
    if (body.content !== undefined) update.content = replaceLegacyCompanyName(body.content, companyName);
    if (body.excerpt !== undefined) update.excerpt = replaceLegacyCompanyName(body.excerpt, companyName);
    if (body.coverImage !== undefined) update.coverImage = replaceLegacyCompanyName(body.coverImage, companyName);
    if (body.category !== undefined) update.category = replaceLegacyCompanyName(body.category, companyName);
    if (body.tags !== undefined) {
      update.tags = normalizeSeoTags(
        replaceLegacyCompanyName(Array.isArray(body.tags) ? JSON.stringify(body.tags) : body.tags, companyName),
        replaceLegacyCompanyName(body.targetKeyword ?? current.targetKeyword, companyName),
      );
    }
    if (body.status !== undefined) {
      update.status = body.status === "published" ? "published" : "draft";
      if (body.status === "published" && !body.publishedAt) update.publishedAt = now;
    }
    if (body.publishedAt !== undefined) update.publishedAt = body.publishedAt;
    if (body.isActive !== undefined) update.isActive = body.isActive;
    if (body.order !== undefined) update.order = Number(body.order) || 0;
    if (body.seoTitle !== undefined) update.seoTitle = replaceLegacyCompanyName(body.seoTitle, companyName);
    if (body.seoDescription !== undefined) update.seoDescription = replaceLegacyCompanyName(body.seoDescription, companyName);
    if (body.seoKeywords !== undefined || body.targetKeyword !== undefined) {
      update.seoKeywords = normalizeSeoKeywords(
        replaceLegacyCompanyName(body.seoKeywords ?? current.seoKeywords, companyName),
        replaceLegacyCompanyName(body.targetKeyword ?? current.targetKeyword, companyName),
      );
    }
    if (body.seoSlug !== undefined || body.slug !== undefined) {
      const slug = normalizeSlug(body.seoSlug ?? body.slug, body.title || "صفحة-seo");
      update.seoSlug = slug;
      update.slug = slug;
    }
    if (body.ogImage !== undefined) update.ogImage = replaceLegacyCompanyName(body.ogImage, companyName);
    if (body.canonicalUrl !== undefined || String(current.canonicalUrl ?? "").trim()) {
      update.canonicalUrl = replaceLegacyCompanyName(canonicalUrl, companyName);
    }

    const [row] = await db.update(seoPagesTable).set(update).where(eq(seoPagesTable.id, id)).returning();
    if (!row) return res.status(404).json({ error: "Not found" });
    await refreshSitemapFile(req);
    return res.json(castRow(row, companyName));
  } catch (error) {
    return res.status(500).json({ error: String(error) });
  }
});

router.delete("/admin/seo-pages/:id", requireAdmin, requireSectionPermission("seo_pages"), async (req, res) => {
  try {
    const id = Number.parseInt(String(req.params.id), 10);
    await db.delete(seoPagesTable).where(eq(seoPagesTable.id, id));
    await refreshSitemapFile(req);
    return res.status(204).send();
  } catch (error) {
    return res.status(500).json({ error: String(error) });
  }
});

export default router;